Matching Ayahs
- = Alif, Laam, Miim. 2:1; 3:1; 29:1; 30:1; 31:1; 32:1
- = Isaan sun warra Gooftaa isaanii biraa qajeelina irra jiran; isaan sun isaantu milkaa'oota. 2:5; 31:5
- = Yaa Ilmaan Israa'iil! Ni'immata koo ishee ani isin irratti oolee fi ani isin uumama (namoota) irra caalchise yaadadhaa. 2:47; 2:122
- = Sun ummata darbeedha. Isaan waan hojjatan isaaniif; isinis waan hojjattan isiniif. Isaan waan dalagaa turan irraas isin hin gaafatamtan. 2:134; 2:141
- = Isaan keessatti barabaraan turu. Adabbiin isaan irraa hin salphifamu; isaaniis hin tursiifaman. 2:162; 3:88
- = Isaan kana booda tawbatanii (of) tolchan malee. Dhugumatti, Rabbiin araaramaa, rahmataa (mararfataa) dha. 3:89; 24:5
- = Isaan kafaraniifi keeyyattoota keenya sobsan – isaan sun warra ibiddaati. 5:10; 5:86
- = Mallattoon Gooftaa isaanii irraa isaanitti hin dhufu, isaan ishee irraa garagalu malee. 6:4; 36:46
- = Dhugumatti, ergamoonni si duraa qishinanis; warri isaan qishinan waan isaan qishinan isaanitti marse. 6:10; 21:41
- = Jedhi: "Ani yoo Gooftaa kiyyaaf ajajamuu dide, adabbii guyyaa guddaa nan sodaadha." 6:15; 39:13
- = Sochiin lafaa isaan qabate; manneen isaanii keessatti jilbeenfatanii (du'anii) bariifatan. 7:78; 7:91
- = Ulee isaa darbate; yeroo san isheen bofa ifa taate. 7:107; 26:32
- = Harka isaa baase; yeroo san isheen warra ilaalanif adii (iftuu) taate. 7:108; 26:33
- = Isaan "Gooftaa uumamaatti amanne" jedhan. 7:121; 26:47
- = Gooftaa Muusaafi Haaruun. 7:122; 26:48
- = Ani (yeroo) isaaniif nan kennadha. Dhugumatti, tooftaan kiyya cimaa dha. 7:183; 68:45
- = Inni isa ergamaa Isaa qajeelfamaafi amantii dhugaa waliin erge; akka ishee amantii hunda irra caalchisuuf, shirkistoonni jibbanillee. 9:33; 61:9
- = Yaa Nabiyyii! Kaafirootaafi munaafiqootaan qabsi; isaanittis cimaa ta'i. Teessoon isaanii jahannam; deebiin isaanii akkam rakkadhaa! 9:73; 66:9
- = Isaan "Yoo kan dhugaa taatan, waadaan kun yoom?" jedhu. 10:48; 21:38; 27:71; 34:29; 36:48; 67:25
- = Dhugumatti, Muusaa mallattooleen keenyaafi raajii ifa ta'e waliin ergine. 11:96; 40:23
- = Dhugumatti, Muusaaf kitaaba kennine; isa keessatti wal dhabame. Odoo jechi Gooftaa kee biraa dabre jiraatee baatee, gidduu isaanitti murteeffama ture. Isaanis dhugumatti isa irraa shakka keessa jiru. 11:110; 41:45
- = Sun Rabbi irratti ulfaataa miti. 14:20; 35:17
- = "Yeroo ani isa tolchee, hafuura koo irraa isa keessa afuufee, isin isaaf sujuuda bu'aa." 15:29; 38:72
- = Malaa'ikonni hunda isaa sujuuda bu'an. 15:30; 38:73
- = (Rabbiin) "Ishee irraa ba'i; dhugumatti ati (isaan) darbatamaa (of irraa fageeffamaa) dha" jedhe. 15:34; 38:77
- = (Ibliis) "Gooftaa kiyya! Yeroo san hanga guyyaa isaan kaasfamaniif na tursiisi" jedhe. 15:36; 38:79
- = (Rabbiin) "Ati warra tursiifamtan irraayi" jedhe. 15:37; 38:80
- = Hanga guyyaa yeroo beekamtuutti." 15:38; 38:81
- = Isaan keessaa gabroota kee filatamtoota malee. 15:40; 38:83
- = Dhugumatti, warri Rabbiin sodaatan ashaakiltiifi burqaalee keessa jiru. 15:45; 51:15
- = (Ibraahiim) "Yeroo san ergamoonni yoo, wanti isin jiru maal?" jedhe. 15:57; 51:31
- = Isaan "Nu ummata yakkaa gara isaanitti ergamnee jirra" jedhan. 15:58; 51:32
- = Warri amananii amantii isaanii miidhaa (kufri) waliin hin makine – isaan warra nagaa qaban; isaanis isantu qajeeloo. 16:42; 29:59
- = Akka waan isaaniif kennine kafaruuf. Kanaaf (yeroo muraasa) qanadhaa; fuuldura beektu. 16:55; 30:34
- = Ergasii karaa (biraa) hordofe. 18:89; 18:92
