- Dogoggora namoota biroo irraa dhiifama raawwadhaa. 7:199
- Yoo shayaana irraa qaanxisni hamtuu isin bira ga’e, Allaahittisabaadhaa. Dhugumatti, Inni dhaga’aa, beekaa. 7:200
