- Rabbiin onneewwan warra Isatti amanan gidduutti jaalala fi tolfamta buusa. 8:63
- Warra eegumsa gaafatan eegaa; gargaaraa isaanis. 9:6
- Mushriiqoonni masjiidawwan Allaah eeguuf hin ta’anu. 9:17
